%root% {
  margin-top: 4rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
}
@media (min-width: 640px) {
  %root% {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

%root% {
  margin: 0;
